import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // 앱 시작 전에 자주 사용하는 폰트 프리로드
  await _preloadFonts();

  runApp(const MyApp());
}

/// 자주 사용하는 폰트를 미리 로드
Future<void> _preloadFonts() async {
  // Noto Sans KR의 다양한 weight 프리로드
  await GoogleFonts.pendingFonts([
    GoogleFonts.notoSansKr(fontWeight: FontWeight.w300),
    GoogleFonts.notoSansKr(fontWeight: FontWeight.w400),
    GoogleFonts.notoSansKr(fontWeight: FontWeight.w500),
    GoogleFonts.notoSansKr(fontWeight: FontWeight.w700),
  ]);

  // 다른 폰트도 필요시 추가
  // await GoogleFonts.pendingFonts([
  //   GoogleFonts.roboto(),
  //   GoogleFonts.poppins(),
  // ]);
}

