class HomePage extends StatelessWidget {
  const HomePage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('폰트 프리로딩')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 폰트가 이미 로드되어 있어 즉시 표시됨
            Text(
              '프리로드된 폰트는 즉시 표시됩니다',
              style: GoogleFonts.notoSansKr(
                fontSize: 20,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 16),
            Text(
              '네트워크 지연 없이 바로 렌더링됩니다.',
              style: GoogleFonts.notoSansKr(fontSize: 16),
            ),
            const SizedBox(height: 32),

            // 폰트 로딩 상태 확인
            FutureBuilder(
              future: GoogleFonts.pendingFonts([
                GoogleFonts.jua(),  // 프리로드하지 않은 폰트
              ]),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const CircularProgressIndicator();
                }
                return Text(
                  '동적으로 로드된 폰트',
                  style: GoogleFonts.jua(fontSize: 24),
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}
